import{_ as a,c as t,o,a3 as i,ag as r,ah as n,ai as c,aj as s}from"./chunks/framework.MI-M1z4O.js";const I=JSON.parse('{"title":"SyncAPIM: AI自律APIセキュリティ監視および仕様ガバナンスプラットフォーム","description":"SyncAPIMは、リアルタイムAPIトラフィック収集、未登録シャドーAPI自動検出、OpenAPI 3.0.1仕様ドリフト診断、インテリジェントWeb・API攻撃遮断（WAF）、および機密情報リアルタイムマスキングを提供するエンタープライズAPIセキュリティ・監視エージェントプラットフォームです。","frontmatter":{"title":"SyncAPIM: AI自律APIセキュリティ監視および仕様ガバナンスプラットフォーム","sidebarTitle":"概要","description":"SyncAPIMは、リアルタイムAPIトラフィック収集、未登録シャドーAPI自動検出、OpenAPI 3.0.1仕様ドリフト診断、インテリジェントWeb・API攻撃遮断（WAF）、および機密情報リアルタイムマスキングを提供するエンタープライズAPIセキュリティ・監視エージェントプラットフォームです。","head":[["meta",{"name":"keywords","content":"SyncAPIM, API監視, APIセキュリティ, WAF, シャドーAPI検知, OpenAPI 3.0仕様診断, 個人情報マスキング, JWT検証, SQLインジェクション遮断, SSRF防御, AgentScope Java, PostgreSQL 18.6"}],["meta",{"property":"og:title","content":"SyncAPIM: AI自律APIセキュリティ監視および仕様ガバナンスプラットフォーム"}],["meta",{"property":"og:description","content":"SyncAPIMは、リアルタイムAPIトラフィック収集、未登録シャドーAPI自動検出、OpenAPI 3.0.1仕様ドリフト診断、インテリジェントWeb・API攻撃遮断（WAF）、および機密情報リアルタイムマスキングを提供します。"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/syncapim/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/syncapim/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncapim/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncapim/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncapim/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncapim/"}]],"sort":1},"headers":[],"relativePath":"ja/syncapim/index.md","filePath":"ja/syncapim/index.md","lastUpdated":1795293539000}'),d={name:"ja/syncapim/index.md"};function l(p,e,m,P,g,A){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="syncapim-ai自律apiセキュリティ監視および仕様ガバナンスプラットフォーム" tabindex="-1">SyncAPIM: AI自律APIセキュリティ監視および仕様ガバナンスプラットフォーム <a class="header-anchor" href="#syncapim-ai自律apiセキュリティ監視および仕様ガバナンスプラットフォーム" aria-label="Permalink to “SyncAPIM: AI自律APIセキュリティ監視および仕様ガバナンスプラットフォーム”">​</a></h1><blockquote><p><strong>非開発者・導入検討ガイド</strong>: わかりやすい製品紹介は<a href="https://apim.empasy.io/ja/" target="_blank" rel="noopener">SyncAPIM製品ホームページ（apim.empasy.io）</a>にて、インストール不要の画面体験は<a href="https://sync.empasy.io/ja/products/sync-apim#demo" target="_blank" rel="noopener">統合デモポータル</a>にてご利用いただけます。また、紹介資料・提案書PDFは<a href="/ja/proposals/">提案書ライブラリ</a>からダウンロードできます。</p></blockquote><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>SyncSeries 4-Tier APIセキュリティ・監視エージェント（<code>SYNC_APIM</code>）</strong>: <code>SyncAPIM</code>は、マイクロサービスやレガシーWASの前段で流通するすべてのAPIトラフィックをリアルタイム収集し、<strong>構文トークンフィンガープリント解析器（<code>SqlXssLexicalTokenizer</code>）</strong>、<strong><code>SyncWatch</code>連携リアルタイム攻撃パターン検知・ピンポイント仮想パッチ（<code>ApimDefensePack</code> &amp; <code>SandboxedDefenseEvaluator</code>）</strong>、<strong>カーネルeBPF遮断</strong>、<strong>未登録シャドーAPI自動カタログ化</strong>、<strong>OpenAPI 3.0.1仕様ドリフト診断</strong>、および<strong>8大個人・金融機密情報の動的マスキング</strong>を自律的に実行します。</p></div><h2 id="_1-コアアーキテクチャおよび技術標準" tabindex="-1">1. コアアーキテクチャおよび技術標準 <a class="header-anchor" href="#_1-コアアーキテクチャおよび技術標準" aria-label="Permalink to “1. コアアーキテクチャおよび技術標準”">​</a></h2><ul><li><strong>標準ネームスペースおよびAPI</strong>: <code>com.empasy.sync.apim</code> / Canonical API Prefix <code>/api/v1/apim/...</code></li><li><strong>パフォーマンス分離型4-JVMマルチプロセスアーキテクチャ</strong>: <ol><li><code>sync-apim-admin</code>（ポート<code>18089</code> / <code>8080</code>）: 統合管理コンソールREST API、時系列統計バッチ（<code>ApimTrafficAggregationService</code>）、<code>SyncApimAgent</code>およびMCPサーバー（<code>/api/v1/apim/mcp</code>）</li><li><code>sync-apim-receiver</code>（ポート<code>18090</code> / <code>8081</code>、TCP <code>5044</code>/<code>5055</code>）: Java 25 Virtual Threadsベースの超高速Lumberjack/Packetbeatパケット受信およびRedis Stream（<code>job_queue</code>）プロデューサー</li><li><code>sync-apim-detector</code>（ポート<code>18092</code> / <code>8090</code>）: Redis Streamコンシューマーワーカー、OpenAPI 3.0.1スキーマ自動推論、6種WAF脅威検知、8種PIIマスキングおよびPostgreSQL 18.6への格納</li><li><code>sync-apim-gateway</code>（ポート<code>18091</code> / <code>8083</code>）: DB/Redisリアルタイム連携動的API遮断フィルター（<code>BlockedApiFilter</code>）およびインラインリバースプロキシゲートウェイ</li></ol></li><li><strong>AI自律エージェントフレームワーク</strong>: <code>AgentScope Java</code>（<code>io.agentscope:agentscope-harness</code>）ベースの仕様ドリフト診断および脅威パケットフォレンジック解説</li><li><strong>PostgreSQL 18.6単一高性能ストレージ</strong>: 負荷の高い外部OpenSearchクラスターを排除し、PostgreSQL 18.6 <code>JSONB</code> + <code>pg_trgm</code> GINインデックスベースの時系列脅威・トラフィックイベント（<code>wapf_detect_event</code>）エンジンへ統合</li><li><strong>動的RBACメニューガバナンス</strong>: Vben Admin <code>PermissionModeEnum.BACK</code>モードと<code>sys_permission</code>単一ソースDBにより、11の監視画面をロール別に動的に提供</li></ul><h2 id="_2-主な機能構成" tabindex="-1">2. 主な機能構成 <a class="header-anchor" href="#_2-主な機能構成" aria-label="Permalink to “2. 主な機能構成”">​</a></h2><h3 id="_2-1-api監視-perm-apim-000" tabindex="-1">2.1 API監視 (<code>perm-apim-000</code>) <a class="header-anchor" href="#_2-1-api監視-perm-apim-000" aria-label="Permalink to “2.1 API監視 (perm-apim-000)”">​</a></h3><ol><li><strong>ホスト監視 (<code>/waf/host</code>)</strong>: 保護対象のAPIゲートウェイ、WAS、Webサーバーホストインベントリ登録および収集エージェントの接続状態監視</li><li><strong>APIカタログ (<code>/waf/endpoint</code>)</strong>: 実トラフィックパケット解析によるAPIエンドポイントの自動検出、リスクスコア算出およびワンクリック即時遮断制御</li><li><strong>API仕様診断 (<code>/waf/api_test</code>)</strong>: OpenAPI 3.0.1仕様書に対する実際のリクエスト・レスポンススキーマの不一致（Contract Drift）および未承認シャドーAPIの自動判定</li><li><strong>トラフィック統計 (<code>/waf/api_statistics</code>)</strong>: エンドポイント別の時系列呼び出し数、ホスト別の上位呼び出し分布およびExcelエクスポート/インポートのサポート</li><li><strong>収集エージェント (<code>/waf/agent</code>)</strong>: サービスドメイン別のトラフィック収集エージェントSHA-256認証キー発行および対象ホストのマッピング管理</li></ol><h3 id="_2-2-apiセキュリティ防御-perm-apim-100" tabindex="-1">2.2 APIセキュリティ防御 (<code>perm-apim-100</code>) <a class="header-anchor" href="#_2-2-apiセキュリティ防御-perm-apim-100" aria-label="Permalink to “2.2 APIセキュリティ防御 (perm-apim-100)”">​</a></h3><ol><li><strong>脅威検知ログ (<code>/waf/request</code>)</strong>: SQL Injection、XSS、SSRF、RCE、Directory Traversal、JWT署名改ざん等のリアルタイム脅威パケット原文および遮断有無のフォレンジック照会</li><li><strong>セキュリティポリシー (<code>/waf/policy</code>)</strong>: 認証、アクセス制御、データ暗号化、権限認可、ネットワークセキュリティ、個人情報保護、侵入検知の7大標準セキュリティポリシーグループの運用（変更時に即座にRedisキャッシュへ同期）</li><li><strong>検知ルール管理 (<code>/waf/rule</code>)</strong>: 正規表現シグネチャパターンおよびJWT完全性検証オプションの定義</li><li><strong>脅威ルール統計 (<code>/waf/rule_statistics</code>)</strong>: 攻撃種別および深刻度レベル別の時系列検知推移と上位攻撃ルールのチャート分析</li><li><strong>機密情報マスキング (<code>/waf/sensitivity</code>)</strong>: 口座番号、メールアドレス、カード番号、住民登録番号、氏名、パスワード、IPアドレス、電話番号など8大機密情報のリアルタイムマスキングルール管理</li><li><strong>警告メール履歴 (<code>/waf/warning_mails</code>)</strong>: 高リスク攻撃の遮断およびシャドーAPI検出時におけるセキュリティ担当者への警告送信履歴の追跡</li></ol><h2 id="実稼働画面および主要ワークフロー" tabindex="-1">実稼働画面および主要ワークフロー <a class="header-anchor" href="#実稼働画面および主要ワークフロー" aria-label="Permalink to “実稼働画面および主要ワークフロー”">​</a></h2><h3 id="_1-apiセキュリティ監視およびリアルタイムトラフィック・脅威統合ダッシュボード" tabindex="-1">1. APIセキュリティ監視およびリアルタイムトラフィック・脅威統合ダッシュボード <a class="header-anchor" href="#_1-apiセキュリティ監視およびリアルタイムトラフィック・脅威統合ダッシュボード" aria-label="Permalink to “1. APIセキュリティ監視およびリアルタイムトラフィック・脅威統合ダッシュボード”">​</a></h3><p>収集・検知・遮断パイプラインが処理するリアルタイムAPIトラフィックの推移、脅威遮断状況、未登録シャドーAPIの検出件数を一目で把握できます。</p><p><img src="'+r+'" alt="SyncAPIM APIセキュリティ監視統合ダッシュボード" loading="lazy"></p><h3 id="_2-実トラフィックベースのapiエンドポイントカタログおよびシャドーapi検知" tabindex="-1">2. 実トラフィックベースのAPIエンドポイントカタログおよびシャドーAPI検知 <a class="header-anchor" href="#_2-実トラフィックベースのapiエンドポイントカタログおよびシャドーapi検知" aria-label="Permalink to “2. 実トラフィックベースのAPIエンドポイントカタログおよびシャドーAPI検知”">​</a></h3><p>実際に流通しているパケットからHTTPメソッド、URIパターン、リクエスト・レスポンスペイロードスキーマを自動推論して未登録シャドーAPIを識別し、ワンクリックで遮断ポリシーを適用します。</p><p><img src="'+n+'" alt="SyncAPIM APIエンドポイントカタログおよびシャドーAPI管理" loading="lazy"></p><h3 id="_3-リアルタイムweb・api脅威検知ログおよび攻撃パケットフォレンジック" tabindex="-1">3. リアルタイムWeb・API脅威検知ログおよび攻撃パケットフォレンジック <a class="header-anchor" href="#_3-リアルタイムweb・api脅威検知ログおよび攻撃パケットフォレンジック" aria-label="Permalink to “3. リアルタイムWeb・API脅威検知ログおよび攻撃パケットフォレンジック”">​</a></h3><p>構文フィンガープリント解析および無停止仮想パッチルールによって検知・遮断されたSQLインジェクション、XSS、SSRF、リモートコード実行攻撃パケットの原文とリスク度を精密に分析します。</p><p><img src="'+c+'" alt="SyncAPIM リアルタイム脅威検知ログおよびパケットフォレンジック" loading="lazy"></p><h3 id="_4-apiセキュリティポリシーおよび個人・金融機密情報の動的マスキング管理" tabindex="-1">4. APIセキュリティポリシーおよび個人・金融機密情報の動的マスキング管理 <a class="header-anchor" href="#_4-apiセキュリティポリシーおよび個人・金融機密情報の動的マスキング管理" aria-label="Permalink to “4. APIセキュリティポリシーおよび個人・金融機密情報の動的マスキング管理”">​</a></h3><p>口座番号、カード番号、住民登録番号、メールアドレス、電話番号など8大機密情報のリアルタイムマスキングルールとエンドポイント別セキュリティポリシーを無停止で制御します。</p><p><img src="'+s+'" alt="SyncAPIM セキュリティポリシーおよび機密情報マスキング設定" loading="lazy"></p><hr><h2 id="_3-ドキュメント構成案内" tabindex="-1">3. ドキュメント構成案内 <a class="header-anchor" href="#_3-ドキュメント構成案内" aria-label="Permalink to “3. ドキュメント構成案内”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ドキュメント名</th><th style="text-align:left;">主な内容</th><th style="text-align:left;">リンク</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>4-JVMアーキテクチャ・DB設計</strong></td><td style="text-align:left;">4つの独立JVMプロセス分離構造、Redis Streamパイプライン、PostgreSQL 18.6の17ドメインテーブル詳細仕様</td><td style="text-align:left;"><a href="/ja/syncapim/architecture">アーキテクチャを見る →</a></td></tr><tr><td style="text-align:left;"><strong>WAF脅威検知・PIIマスキング</strong></td><td style="text-align:left;">シャドーAPI検知、OpenAPI 3.0.1 Contract Drift比較監査、6大攻撃検知ルールおよび8大機密情報マスキングポリシー</td><td style="text-align:left;"><a href="/ja/syncapim/waf-and-pii-governance">セキュリティガバナンスを見る →</a></td></tr><tr><td style="text-align:left;"><strong>MCPツール・REST API</strong></td><td style="text-align:left;"><code>SyncVerse</code>管制塔連携用6大MCPツール（<code>apim_discover_shadow_apis</code>等）および<code>/api/v1/apim</code> REST APIリファレンス</td><td style="text-align:left;"><a href="/ja/syncapim/mcp-tools">MCP・APIを見る →</a></td></tr><tr><td style="text-align:left;"><strong>導入FAQ</strong></td><td style="text-align:left;">オンプレミス閉域網構築、4-JVMパフォーマンス分離、OpenSearch代替アーキテクチャ等に関するよくある質問</td><td style="text-align:left;"><a href="/ja/syncapim/enterprise-faq">FAQを見る →</a></td></tr></tbody></table>',26)])])}const y=a(d,[["render",l]]);export{I as __pageData,y as default};
